        // KHR_materials_clearcoat
        if (mat.clearCoat > 0) {
            const clearcoatExt = {
                // Parser multiplies by 0.25, so we divide by 0.25 (multiply by 4) to reverse
                clearcoatFactor: Math.min(mat.clearCoat * 4, 1)
