                a = emitter.qVelocity[cf + 1];
                b = emitter.qVelocity[cc + 1];
                velocityVec.y = a + (b - a) * c;
                a = emitter.qVelocity[cf + 2];
                b = emitter.qVelocity[cc + 2];
                velocityVec.z = a + (b - a) * c;

